class Solution {
public:
    int minimumTotalPrice(int n, std::vector<std::vector<int>>& edges, std::vector<int>& price, std::vector<std::vector<int>>& trips) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        std::vector<int> count(n, 0);
        for (const auto& t : trips) {
            std::vector<int> path;
            auto find_path = [&](auto& self, int curr, int parent, int target) -> bool {
                path.push_back(curr);
                if (curr == target) return true;
                for (int nxt : adj[curr]) {
                    if (nxt != parent && self(self, nxt, curr, target)) return true;
                }
                path.pop_back();
                return false;
            };
            find_path(find_path, t[0], -1, t[1]);
            for (int u : path) count[u]++;
        }
        auto dfs = [&](auto& self, int u, int p) -> std::pair<int, int> {
            int no_half = count[u] * price[u];
            int half = count[u] * (price[u] / 2);
            for (int v : adj[u]) {
                if (v != p) {
                    auto [c_no_half, c_half] = self(self, v, u);
                    no_half += std::min(c_no_half, c_half);
                    half += c_no_half;
                }
            }
            return {no_half, half};
        };
        auto [r1, r2] = dfs(dfs, 0, -1);
        return std::min(r1, r2);
    }
};

class Solution {
    public int minimumTotalPrice(int n, int[][] edges, int[] price, int[][] trips) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int[] count = new int[n];
        for (int[] t : trips) {
            List<Integer> path = new ArrayList<>();
            findPath(t[0], -1, t[1], adj, path);
            for (int u : path) count[u]++;
        }
        int[] res = dfs(0, -1, adj, price, count);
        return Math.min(res[0], res[1]);
    }

    private boolean findPath(int curr, int p, int target, List<List<Integer>> adj, List<Integer> path) {
        path.add(curr);
        if (curr == target) return true;
        for (int nxt : adj.get(curr)) {
            if (nxt != p && findPath(nxt, curr, target, adj, path)) return true;
        }
        path.remove(path.size() - 1);
        return false;
    }

    private int[] dfs(int u, int p, List<List<Integer>> adj, int[] price, int[] count) {
        int noHalf = count[u] * price[u];
        int half = count[u] * (price[u] / 2);
        for (int v : adj.get(u)) {
            if (v != p) {
                int[] child = dfs(v, u, adj, price, count);
                noHalf += Math.min(child[0], child[1]);
                half += child[0];
            }
        }
        return new int[]{noHalf, half};
    }
}

var minimumTotalPrice = function(n, edges, price, trips) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const count = new Array(n).fill(0);
    for (const [start, end] of trips) {
        const path = [];
        function findPath(curr, parent) {
            path.push(curr);
            if (curr === end) return true;
            for (const nxt of adj[curr]) {
                if (nxt !== parent && findPath(nxt, curr)) return true;
            }
            path.pop();
            return false;
        }
        findPath(start, -1);
        for (const node of path) count[node]++;
    }
    function dfs(u, p) {
        let noHalf = count[u] * price[u];
        let half = count[u] * Math.floor(price[u] / 2);
        for (const v of adj[u]) {
            if (v !== p) {
                const [cNoHalf, cHalf] = dfs(v, u);
                noHalf += Math.min(cNoHalf, cHalf);
                half += cNoHalf;
            }
        }
        return [noHalf, half];
    }
    const [r1, r2] = dfs(0, -1);
    return Math.min(r1, r2);
};
